#include "driver_core.h"
int driver_transition(struct driver_instance *d,enum driver_state n){if(!d)return -1;enum driver_state s=d->state;int ok=(s==DRIVER_NEW&&n==DRIVER_DISCOVERED)||(s==DRIVER_DISCOVERED&&n==DRIVER_MATCHED)||(s==DRIVER_MATCHED&&n==DRIVER_PROBED)||(s==DRIVER_PROBED&&n==DRIVER_ACQUIRED)||(s==DRIVER_ACQUIRED&&n==DRIVER_CONFIGURED)||(s==DRIVER_CONFIGURED&&n==DRIVER_REGISTERED)||(s==DRIVER_REGISTERED&&n==DRIVER_SERVING)||(s==DRIVER_SERVING&&n==DRIVER_SUSPENDED)||(s==DRIVER_SUSPENDED&&n==DRIVER_SERVING)||(s==DRIVER_SERVING&&n==DRIVER_FAILED)||(s==DRIVER_SUSPENDED&&n==DRIVER_FAILED)||(n==DRIVER_REMOVED&&(s==DRIVER_DISCOVERED||s==DRIVER_MATCHED||s==DRIVER_PROBED||s==DRIVER_ACQUIRED||s==DRIVER_CONFIGURED||s==DRIVER_REGISTERED||s==DRIVER_SERVING||s==DRIVER_FAILED||s==DRIVER_SUSPENDED));if(!ok)return -1;d->state=n;return 0;}
int driver_resource_acquire(struct driver_instance *d,uint32_t r){if(!d||r>=DRIVER_MAX_RESOURCES||d->state==DRIVER_REMOVED||(d->resources&(1U<<r)))return -1;d->resources|=1U<<r;return 0;}
int driver_resource_release(struct driver_instance *d,uint32_t r){if(!d||r>=DRIVER_MAX_RESOURCES||!(d->resources&(1U<<r))||!d->release)return -1;if(d->release(d->context,r)!=0)return -2;d->resources&=~(1U<<r);return 0;}
int driver_cleanup(struct driver_instance *d){if(!d)return -1;for(uint32_t i=DRIVER_MAX_RESOURCES;i>0;i--)if(d->resources&(1U<<(i-1)))if(driver_resource_release(d,i-1)!=0)return -2;if(d->state!=DRIVER_REMOVED){if(driver_transition(d,DRIVER_REMOVED)!=0)return -1;}return 0;}
